// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import {
  createStarStressGraph,
  STAR_STRESS_ROOT_ID,
} from "../../../main/frontend/graph-explorer/graph-fixtures.ts";
import {
  centerTransformOn,
  panTransformBy,
  zoomTransformAt,
} from "../../../main/frontend/graph-explorer/graph-viewport.ts";

test("the stress fixture is a deterministic 300-leaf star", () => {
  const first = createStarStressGraph(300, 42);
  const second = createStarStressGraph(300, 42);

  assert.deepEqual(first, second);
  assert.equal(first.nodes.length, 301);
  assert.equal(first.edges.length, 300);
  assert.equal(first.revision, 42);
  assert.ok(first.edges.every((edge) => edge.source === STAR_STRESS_ROOT_ID));
  assert.equal(new Set(first.nodes.map((node) => node.id)).size, 301);
  assert.deepEqual(
    Object.fromEntries(
      ["iri", "literal", "blank"].map((kind) => [
        kind,
        first.nodes.filter((node) => node.kind === kind).length,
      ]),
    ),
    { iri: 226, literal: 50, blank: 25 },
  );
  assert.ok(
    first.nodes.some((node) => node.language === "en") &&
      first.nodes.some((node) => node.language === "nb"),
  );
  assert.ok(
    first.nodes.some((node) => node.datatype?.endsWith("#integer")) &&
      first.nodes.some((node) => node.datatype?.endsWith("#date")),
  );
  assert.ok(
    new Set(
      first.nodes.slice(1).map((node) =>
        Math.round(
          Math.hypot(node.x - first.nodes[0].x, node.y - first.nodes[0].y),
        ),
      ),
    ).size > 8,
    "the leaves should occupy multiple rings rather than one overlapping orbit",
  );
  let approximateOverlaps = 0;
  const leaves = first.nodes.slice(1);
  for (let left = 0; left < leaves.length; left += 1) {
    for (let right = left + 1; right < leaves.length; right += 1) {
      if (
        Math.abs(leaves[left].x - leaves[right].x) < 154 &&
        Math.abs(leaves[left].y - leaves[right].y) < 54
      ) {
        approximateOverlaps += 1;
      }
    }
  }
  assert.equal(
    approximateOverlaps,
    0,
    "the deterministic seed should not begin with overlapping leaf boxes",
  );
});

test("repeated pan and zoom operations remain finite and preserve the focal point", () => {
  const viewport = { width: 1280, height: 780 };
  const focus = { x: 640, y: 390 };
  let transform = centerTransformOn(focus, 0.72, viewport);

  for (let index = 0; index < 600; index += 1) {
    const focalPoint = {
      x: 180 + (index % 13) * 70,
      y: 120 + (index % 9) * 55,
    };
    const graphXBefore = (focalPoint.x - transform.x) / transform.k;
    const graphYBefore = (focalPoint.y - transform.y) / transform.k;
    transform = zoomTransformAt(
      transform,
      index % 2 === 0 ? 1.018 : 0.982,
      focalPoint,
    );
    assert.ok(Math.abs((focalPoint.x - transform.x) / transform.k - graphXBefore) < 1e-8);
    assert.ok(Math.abs((focalPoint.y - transform.y) / transform.k - graphYBefore) < 1e-8);
    transform = panTransformBy(transform, {
      x: (index % 7) - 3,
      y: (index % 11) - 5,
    });
    assert.ok(Object.values(transform).every(Number.isFinite));
  }

  assert.ok(transform.k >= 0.24 && transform.k <= 2.8);
});

